    {
      "id": "obs:8",
      "text": "Gudrun wanders for a long time and hesitates before asking the kings about Sigurd.",
      "category": "sequence",
      "evidence_refs": ["ev:7"]
    },
    {
      "id": "obs:9",
      "text": "Gunnar hangs his head, and Hogni tells Gudrun of Sigurd's cruel slaying, saying Sigurd lies smitten to death across the water, given over to wolves.",
